package com.nonet.app;

import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.VpnService;import android.os.Bundle;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;
import org.json.JSONObject;import java.util.*;import java.text.*;

public class MainActivity extends Activity {
 private final int navy=Color.rgb(11,19,43),teal=Color.rgb(22,160,133),pale=Color.rgb(242,247,250); private android.content.SharedPreferences prefs; private LinearLayout root; private String selectedPlan="monthly",contactMethod="WhatsApp"; private static final int VPN_REQUEST=91;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("nonet",MODE_PRIVATE);scheduleVerification();if(!prefs.getBoolean("intro_seen",false))showIntro();else showHome(); verifyInBackground();}
 private void scheduleVerification(){PeriodicWorkRequest req=new PeriodicWorkRequest.Builder(SubscriptionWorker.class,3,java.util.concurrent.TimeUnit.DAYS).build();WorkManager.getInstance(this).enqueueUniquePeriodicWork("nonet_subscription_check",ExistingPeriodicWorkPolicy.KEEP,req);}
 private String deviceId(){String id=prefs.getString("device_id",null);if(id==null){id=UUID.randomUUID().toString();prefs.edit().putString("device_id",id).apply();}return id;}
 private void verifyInBackground(){new Thread(()->{try{JSONObject j=ApiClient.request(this,"GET","/api/subscription/status?deviceId="+deviceId(),null,null);JSONObject s=j.optJSONObject("subscription");boolean active=s!=null&&"active".equals(s.optString("status"));String expiry=s==null?null:s.optString("expiresAt",null);if(active&&expiry!=null&&!"null".equals(expiry)){try{active=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss",Locale.US).parse(expiry.substring(0,19)).after(new Date());}catch(Exception ignored){}}final boolean activeResult=active;prefs.edit().putBoolean("subscription_active",activeResult).putLong("last_server_check",System.currentTimeMillis()).apply();runOnUiThread(()->{if(!activeResult){Toast.makeText(this,"لا يوجد اشتراك فعّال حالياً",Toast.LENGTH_SHORT).show();} });}catch(Exception e){/* Server/network failure must not consume grace or suspend a previously active subscription. */}}).start();}
 private void showIntro(){root=page();root.addView(title("أهلاً بك في No Net",28,navy));root.addView(card("تحكّم باتصال التطبيقات بالإنترنت."));root.addView(card("• يحتاج التطبيق إلى الإنترنت عند أول تشغيل للتحقق من الاشتراك.\n• سيجري التحقق الدوري كل 3 أيام.\n• عند تعذر الاتصال بالخادم بسبب عطل تقني، لا يُوقف الاشتراك ولا تُستهلك فرصة السماح.\n• قد يؤدي الحجب إلى توقف إشعارات التطبيق المحجوب.\n• يعتمد الحجب على خدمة VPN محلية في أندرويد، ويجب الموافقة على نافذة النظام."));root.addView(card("سياسة التحقق: عند طلب تحقق دوري، تمنح مهلة 12 ساعة لإتمامه. توجد فرصة سماح واحدة فقط لكل مشترك؛ وتُسجل الأحداث في النظام. اقرأ السياسة قبل الاشتراك."));Button b=button("قرأت التعليمات — متابعة");b.setOnClickListener(v->{prefs.edit().putBoolean("intro_seen",true).apply();showHome();});root.addView(b);setContentView(wrap(root));}
 private void showHome(){root=page();root.addView(title("No Net",32,navy));root.addView(text("تحكّم باتصال تطبيقاتك",17,Color.DKGRAY));root.addView(card(prefs.getBoolean("subscription_active",false)?"حالة الاشتراك: فعّال على هذا الجهاز":"حالة الاشتراك: يلزم التحقق أو الاشتراك"));Button apps=button("📱 التطبيقات وإعدادات الحجب");apps.setOnClickListener(v->showApps());root.addView(apps);Button toggle=button("تشغيل الحجب / طلب إذن VPN");toggle.setOnClickListener(v->enableVpn());root.addView(toggle);Button refresh=button("التحقق من الاشتراك الآن");refresh.setOnClickListener(v->{verifyInBackground();Toast.makeText(this,"جارٍ التحقق من الخادم…",Toast.LENGTH_SHORT).show();});root.addView(refresh);Button plans=button("💳 الاشتراكات وطلب الاشتراك");plans.setOnClickListener(v->showPlans());root.addView(plans);Button settings=button("⚙️ إعدادات الاتصال بالخادم");settings.setOnClickListener(v->showSettings());root.addView(settings);root.addView(text("يجب ضبط رابط الخادم وتشغيله قبل استخدام الاشتراكات المتصلة.",13,Color.GRAY));setContentView(wrap(root));}
 private void enableVpn(){if(!prefs.getBoolean("subscription_active",false)){new AlertDialog.Builder(this).setMessage("يجب التحقق من اشتراك فعّال أولاً. تأكد من ضبط رابط الخادم.").setPositiveButton("حسناً",null).show();return;}Intent i=VpnService.prepare(this);if(i!=null)startActivityForResult(i,VPN_REQUEST);else startVpn();}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==VPN_REQUEST){if(c==RESULT_OK)startVpn();else Toast.makeText(this,"لم يتم منح إذن VPN",Toast.LENGTH_LONG).show();}}
 private void startVpn(){try{Intent svc=new Intent(this,BlockVpnService.class);if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(svc);else startService(svc);Toast.makeText(this,"تم تشغيل خدمة No Net",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"تعذر تشغيل الحجب: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 private void refreshVpn(){try{Intent svc=new Intent(this,BlockVpnService.class).setAction(BlockVpnService.ACTION_REFRESH);if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(svc);else startService(svc);}catch(Exception ignored){}}
 private void showApps(){root=page();root.addView(title("التطبيقات",27,navy));root.addView(card("اختر وضع الحجب لكل تطبيق. الحجب الفعلي يعمل فقط مع اشتراك فعّال وبعد تشغيل خدمة VPN."));List<ApplicationInfo> apps=new ArrayList<>();PackageManager pm=getPackageManager();for(ApplicationInfo ai:pm.getInstalledApplications(PackageManager.GET_META_DATA)){if(pm.getLaunchIntentForPackage(ai.packageName)!=null&&!ai.packageName.equals(getPackageName()))apps.add(ai);}Collections.sort(apps,(a,b)->pm.getApplicationLabel(a).toString().compareToIgnoreCase(pm.getApplicationLabel(b).toString()));for(ApplicationInfo ai:apps){String key="mode_"+ai.packageName;String cur=prefs.getString(key,"لا يوجد");LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setPadding(14,10,14,10);item.setBackground(round(Color.WHITE,16));TextView n=text(pm.getApplicationLabel(ai).toString(),17,navy);n.setTypeface(null,Typeface.BOLD);item.addView(n);item.addView(text(ai.packageName,10,Color.GRAY));Button mode=button(cur.equals("لا يوجد")?"اختيار نوع الحجب":"الحالي: "+cur+" ✎");mode.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("نوع الحجب — "+pm.getApplicationLabel(ai)).setSingleChoiceItems(new String[]{"بدون حجب","بيانات الهاتف فقط","الواي فاي فقط","بيانات الهاتف والواي فاي"},modeIndex(prefs.getString(key,"لا يوجد")),(d,w)->{String[] vals={"لا يوجد","بيانات الهاتف فقط","الواي فاي فقط","الاثنان معاً"};prefs.edit().putString(key,vals[w]).apply();d.dismiss();refreshVpn();showApps();}).setNegativeButton("إلغاء",null).show());item.addView(mode);root.addView(item);}Button back=button("رجوع للرئيسية");back.setOnClickListener(v->showHome());root.addView(back);setContentView(wrap(root));}
 private int modeIndex(String s){if(s.equals("بيانات الهاتف فقط"))return 1;if(s.equals("الواي فاي فقط"))return 2;if(s.equals("الاثنان معاً"))return 3;return 0;}
 private void showPlans(){root=page();root.addView(title("الاشتراكات",27,navy));TextView prices=card("شهري: 1.50 دولار\nسنوي: 10 دولارات\nمدى الحياة: 30 دولاراً\nتُحدّث المبالغ بالليرة السورية من الخادم.");root.addView(prices);new Thread(()->{try{JSONObject cfg=ApiClient.request(this,"GET","/api/config",null,null);JSONObject ps=cfg.optJSONObject("plans");if(ps!=null){String val="شهري: 1.50$ — "+ps.optJSONObject("monthly").optInt("syp")+" ل.س\nسنوي: 10$ — "+ps.optJSONObject("yearly").optInt("syp")+" ل.س\nمدى الحياة: 30$ — "+ps.optJSONObject("lifetime").optInt("syp")+" ل.س";runOnUiThread(()->prices.setText(val));}}catch(Exception ignored){}}).start();String[] names={"شهري — 1.50$","سنوي — 10$","مدى الحياة — 30$"};new AlertDialog.Builder(this).setTitle("اختر الاشتراك").setSingleChoiceItems(names,0,(d,w)->selectedPlan=w==0?"monthly":w==1?"yearly":"lifetime").setPositiveButton("متابعة",(d,w)->showRequestForm()).setNegativeButton("إلغاء",null).show();Button req=button("طلب اشتراك");req.setOnClickListener(v->showRequestForm());root.addView(req);Button back=button("رجوع");back.setOnClickListener(v->showHome());root.addView(back);setContentView(wrap(root));}
 private void showRequestForm(){root=page();root.addView(title("طلب اشتراك",26,navy));EditText phone=new EditText(this);phone.setSingleLine(true);phone.setHint("رقم التواصل مع رمز البلد");root.addView(phone);Spinner contact=new Spinner(this);String[] methods={"WhatsApp","Telegram","SMS"};contact.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,methods));root.addView(text("طريقة التواصل المفضلة",16,navy));root.addView(contact);Button submit=button("إرسال طلب الاشتراك");submit.setOnClickListener(v->{String p=phone.getText().toString().trim();if(p.length()<5){phone.setError("أدخل رقم تواصل صحيحاً");return;}contactMethod=String.valueOf(contact.getSelectedItem());JSONObject body=new JSONObject();try{body.put("deviceId",deviceId());body.put("plan",selectedPlan);body.put("contactMethod",contactMethod);body.put("phone",p);}catch(Exception ignored){}submit.setEnabled(false);new Thread(()->{try{JSONObject out=ApiClient.request(this,"POST","/api/subscription/request",body,null);runOnUiThread(()->new AlertDialog.Builder(this).setTitle("تم استلام الطلب").setMessage(out.optString("message","ستتواصل معك الإدارة خلال مدة أقصاها 6 ساعات.")+"\nرقم الطلب: "+out.optString("requestCode")).setPositiveButton("حسناً",(dd,ww)->showHome()).show());}catch(Exception e){runOnUiThread(()->{submit.setEnabled(true);new AlertDialog.Builder(this).setMessage("تعذر إرسال الطلب: "+e.getMessage()+"\nتأكد من رابط الخادم والاتصال بالإنترنت.").setPositiveButton("حسناً",null).show();});}}).start();});root.addView(submit);Button back=button("رجوع");back.setOnClickListener(v->showPlans());root.addView(back);setContentView(wrap(root));}
 private void showSettings(){root=page();root.addView(title("إعدادات الاتصال",26,navy));EditText url=new EditText(this);url.setSingleLine(true);url.setHint("https://api.example.com");url.setText(prefs.getString("server_url",""));root.addView(text("رابط الخادم المنشور عبر HTTPS",16,navy));root.addView(url);Button save=button("حفظ وتجربة الخادم");save.setOnClickListener(v->{String u=url.getText().toString().trim().replaceAll("/+$","");if(!u.startsWith("https://")){url.setError("استخدم رابط HTTPS آمن");return;}prefs.edit().putString("server_url",u).apply();new Thread(()->{try{JSONObject j=ApiClient.request(this,"GET","/health",null,null);runOnUiThread(()->new AlertDialog.Builder(this).setMessage("اتصال ناجح بالخادم: "+j.optString("service")).setPositiveButton("حسناً",(d,w)->showHome()).show());}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage("فشل الاتصال: "+e.getMessage()).setPositiveButton("حسناً",null).show());}}).start();});root.addView(save);Button back=button("رجوع");back.setOnClickListener(v->showHome());root.addView(back);setContentView(wrap(root));}
 private LinearLayout page(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(18,20,18,24);l.setBackgroundColor(pale);return l;}private ScrollView wrap(LinearLayout l){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(l);return s;}private TextView title(String s,int z,int c){TextView t=text(s,z,c);t.setTypeface(null,Typeface.BOLD);t.setPadding(0,10,0,14);return t;}private TextView text(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);t.setPadding(2,7,2,7);return t;}private TextView card(String s){TextView t=text(s,16,navy);t.setPadding(15,15,15,15);t.setBackground(round(Color.WHITE,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,12);t.setLayoutParams(p);return t;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(round(teal,15));b.setPadding(10,12,10,12);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);b.setLayoutParams(p);return b;}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
}
